fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let n = a.len();

    // Choose a split point so that:
    // - left.len() + right.len() == n
    // - left + right == original order
    // - if n > 1 then both parts are strictly shorter than n
    let mid = if n <= 1 { n } else { n / 2 }; // for n>1, mid in [1, n-1]

    let left = a[..mid].to_vec();
    let right = a[mid..].to_vec();
    (left, right)
}